head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil05502";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — today

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_nowVars();
        await scwin.init_rowCopy();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil05502.onpageload' });
    }
};

/**
 * @method
 * @name init_nowVars
 * @description 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님)
 * @returns {void}
 * @hidden N
 */
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("today")) { pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_isurCd", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["isurCd"] ?? ""); } },
        { childId: "ipt_comNm", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["comNm"] ?? ""); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Confirm_onclick
 * @description btn_Confirm 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Confirm_onclick = async function(e){
    try {
        await scwin.confirm()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05502.btn_Confirm_onclick' }); }
};

/**
 * @method
 * @name btn_Clear_onclick
 * @description btn_Clear 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Clear_onclick = function(e){
    try {
        scwin.clear()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05502.btn_Clear_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Confirm
 * @description Confirm 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Confirm = async function () {
    const sbmOptions = {
        id: "tx_fn_Confirm",
        method: "post",
        action: "/list/supportIR.do",
        ref: "dma_ConfirmReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/list/supportIR.do",
        ref: "dma_loadListReq",
        target: "dlt_hhArray=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name confirm
 * @description confirm 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.confirm = async function () {
    if (await scwin.elementChk()) {
        if (await $c.win.confirm("등록하시겠습니까?")) {
            $c.util.getComponent('dma_ConfirmReq').set('method', "registerIR");
            $c.util.getComponent('dma_ConfirmReq').set('command', "register");
            await scwin.tx_fn_Confirm();
        }
    }
};

/**
 * @method
 * @name clear
 * @description clear 처리
 * @returns {void}
 * @hidden N
 */
scwin.clear = function () {
    $c.util.getComponent('dma_ConfirmReq').reset();
};

/**
 * @method
 * @name elementChk
 * @description element Chk 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.elementChk = async function () {
    const form = (document.SupportIRForm || { elements: [] });
    if ($c.util.getComponent('ipt_ceoNm').getValue()== null || ($c.util.getComponent('ipt_ceoNm').getValue() == null ? '' : String($c.util.getComponent('ipt_ceoNm').getValue())) === '') {
        await $c.win.alert("대표이사를 입력하십시오.");
        $c.util.getComponent("ipt_ceoNm").focus();
        return false;
    } else {
        if ($c.util.getComponent('cal_irHoldDate').getValue()== null || ($c.util.getComponent('cal_irHoldDate').getValue() == null ? '' : String($c.util.getComponent('cal_irHoldDate').getValue())) === '') {
            await $c.win.alert("IR 날짜를 입력하십시오.");
            $c.util.getComponent("cal_irHoldDate").focus();
            return false;
        } else {
            if ($c.util.getComponent('ipt_holdLoc').getValue()== null || ($c.util.getComponent('ipt_holdLoc').getValue() == null ? '' : String($c.util.getComponent('ipt_holdLoc').getValue())) === '') {
                await $c.win.alert("개최장소를 입력하십시오.");
                $c.util.getComponent("ipt_holdLoc").focus();
                return false;
            } else {
                if ($c.util.getComponent('ipt_irChrgNm').getValue()== null || ($c.util.getComponent('ipt_irChrgNm').getValue() == null ? '' : String($c.util.getComponent('ipt_irChrgNm').getValue())) === '') {
                    await $c.win.alert("담당자 성명을 입력하십시오.");
                    $c.util.getComponent("ipt_irChrgNm").focus();
                    return false;
                } else {
                    if ($c.util.getComponent('ipt_irChrgTelNo').getValue()== null || ($c.util.getComponent('ipt_irChrgTelNo').getValue() == null ? '' : String($c.util.getComponent('ipt_irChrgTelNo').getValue())) === '') {
                        await $c.win.alert("담당자 전화번호를 입력하십시오.");
                        $c.util.getComponent("ipt_irChrgTelNo").focus();
                        return false;
                    } else {
                        if (!await (async (c) => { const raw = String((c && c.getValue) ? (c.getValue() ?? "") : ""); if (raw.length === 0) { return true; } const v = raw.split("-").join("").split("/").join(""); if (c && c.setValue) { c.setValue(v); } const lbl = "IR일시"; const lp = lbl ? (lbl + ": ") : ""; if (v.length !== 8) { await $c.win.alert(lp + "날짜는 8 자리 YYYYMMDD 형식입니다."); if (c && c.focus) { c.focus(); } return false; } let digits = true; for (let i = 0; i < v.length; i++) { const ch = v.charAt(i); if (ch < "0" || ch > "9") { digits = false; break; } } if (!digits) { await $c.win.alert(lp + "숫자만 입력가능합니다."); if (c && c.focus) { c.focus(); } return false; } const mm = Number(v.substring(4, 6)); if (mm > 12 || mm < 1) { await $c.win.alert(lp + "달은 1 에서 12 사이여야 합니다."); if (c && c.focus) { c.focus(); } return false; } if (!$c.date.checkCalendarFormat(c, "yyyyMMdd", { clearOnInvalid: false })) { await $c.win.alert(lp + " 존재하지 않는 날짜입니다."); if (c && c.focus) { c.focus(); } return false; } return true; })($c.util.getComponent('cal_irHoldDate'))) {
                            return false;
                        } else {
                            if ($c.util.getComponent('cal_irHoldDate').getValue()< (String(((dma_pageContext.get("today") ?? "")) == null ? '' : ((dma_pageContext.get("today") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("today") ?? "")) == null ? '' : ((dma_pageContext.get("today") ?? ""))))) {
                                await $c.win.alert("IR일시에서 과거날짜는 선택하실 수 없습니다.");
                                $c.util.getComponent("cal_irHoldDate").focus();
                                return false;
                            }
                        }
                    }
                }
            }
        }
    }
    return true;
};
